from pathlib import Path

project = Path(__file__).resolve().parent
css_file = project / "static" / "css" / "style.css"
marker = "BATTLE RESULTS UI FIX"

if not css_file.exists():
    print("ERROR: static\\css\\style.css was not found.")
    print("Extract this ZIP directly inside the ML_Algorithm_Battle_Arena folder.")
    input("Press Enter to close...")
    raise SystemExit(1)

current = css_file.read_text(encoding="utf-8", errors="replace")
if marker in current:
    print("The Battle Results UI fix is already installed.")
else:
    css_file.write_text(current.rstrip() + "\n\n" + '\n\n/* =====================================================\n   BATTLE RESULTS UI FIX\n   Repairs the results container retaining the empty-state\n   flex layout after JavaScript renders the actual results.\n   Keeps the Clean & Bold white / black / cobalt theme.\n===================================================== */\n\n#battle-results.empty-state,\n#battle-results {\n    display: block !important;\n    width: 100%;\n    min-width: 0;\n    padding: 28px;\n    background: #ffffff;\n    border: 1px solid #dfe2e8;\n    border-radius: 10px;\n    box-shadow: 0 5px 18px rgba(21, 23, 28, 0.04);\n}\n\n#battle-results > h2 {\n    display: block;\n    margin: 0 0 8px;\n    color: #15171c;\n    font-size: 28px;\n    font-weight: 800;\n    line-height: 1.25;\n}\n\n#battle-results > .battle-summary {\n    display: block;\n    margin: 0 0 24px;\n    color: #626975;\n    font-size: 14px;\n    line-height: 1.6;\n}\n\n#battle-results > .battle-winner {\n    display: block;\n    width: 100%;\n    margin: 0 0 26px;\n    padding: 24px 26px;\n    background: #edf2ff;\n    border: 1px solid #d8e2ff;\n    border-left: 5px solid #2457e6;\n    border-radius: 8px;\n}\n\n#battle-results .winner-eyebrow {\n    display: block;\n    margin-bottom: 8px;\n    color: #2457e6;\n    font-size: 11px;\n    font-weight: 800;\n    letter-spacing: 1px;\n}\n\n#battle-results .battle-winner h3 {\n    display: block;\n    margin: 0 0 8px;\n    color: #15171c;\n    font-size: 25px;\n    font-weight: 800;\n    line-height: 1.3;\n}\n\n#battle-results .battle-winner p {\n    display: block;\n    margin: 0;\n    color: #343b48;\n    font-size: 15px;\n    line-height: 1.6;\n}\n\n#battle-results > .leaderboard-section {\n    display: block;\n    width: 100%;\n    margin: 0 0 28px;\n    padding: 22px;\n    background: #ffffff;\n    border: 1px solid #dfe2e8;\n    border-radius: 9px;\n}\n\n#battle-results > h3 {\n    display: block;\n    margin: 30px 0 16px;\n    color: #15171c;\n    font-size: 21px;\n    font-weight: 800;\n    line-height: 1.3;\n}\n\n#battle-results .leaderboard-table,\n#battle-results .results-table {\n    width: 100%;\n    min-width: 620px;\n    border-collapse: collapse;\n    background: #ffffff;\n    text-align: left;\n}\n\n#battle-results .leaderboard-table th,\n#battle-results .results-table th {\n    padding: 14px 16px;\n    background: #f0f2f6;\n    color: #444a55;\n    font-size: 12px;\n    font-weight: 800;\n    white-space: nowrap;\n}\n\n#battle-results .leaderboard-table td,\n#battle-results .results-table td {\n    padding: 15px 16px;\n    border-top: 1px solid #dfe2e8;\n    color: #252a33;\n    font-size: 14px;\n    vertical-align: middle;\n}\n\n#battle-results .leaderboard-winner,\n#battle-results .results-table .winning-row {\n    background: #edf2ff;\n}\n\n#battle-results .winner-status {\n    color: #2457e6;\n    font-weight: 800;\n    white-space: nowrap;\n}\n\n#battle-results > .results-table,\n#battle-results > table {\n    display: table;\n    width: 100%;\n    min-width: 620px;\n}\n\n#battle-results .results-table-scroll,\n#battle-results .table-scroll {\n    width: 100%;\n    overflow-x: auto;\n}\n\n#battle-results .metric-charts-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 16px;\n    width: 100%;\n}\n\n#battle-results .metric-chart-card {\n    min-width: 0;\n    padding: 20px;\n    background: #ffffff;\n    border: 1px solid #dfe2e8;\n    border-radius: 9px;\n}\n\n#battle-results .confusion-matrix-section {\n    display: block;\n    width: 100%;\n    margin: 18px 0;\n    padding: 20px;\n    overflow-x: auto;\n    background: #ffffff;\n    border: 1px solid #dfe2e8;\n    border-radius: 9px;\n}\n\n#battle-results .confusion-matrix-section h4 {\n    margin: 0 0 14px;\n    font-size: 16px;\n    font-weight: 750;\n}\n\n#battle-results .confusion-matrix {\n    width: auto;\n    min-width: 280px;\n    border-collapse: collapse;\n}\n\n#battle-results .confusion-matrix th,\n#battle-results .confusion-matrix td {\n    min-width: 58px;\n    padding: 12px 15px;\n    border: 1px solid #dfe2e8;\n    text-align: center;\n}\n\n#battle-results .confusion-matrix th {\n    background: #f1f4ff;\n    color: #1b3fba;\n}\n\n#battle-results .matrix-correct {\n    background: #dfe8ff;\n    color: #173cae;\n    font-weight: 800;\n}\n\n@media (max-width: 900px) {\n    #battle-results.empty-state,\n    #battle-results {\n        padding: 18px;\n    }\n\n    #battle-results .metric-charts-grid {\n        grid-template-columns: 1fr;\n    }\n\n    #battle-results > .battle-winner {\n        padding: 20px;\n    }\n}\n', encoding="utf-8")
    print("SUCCESS: Battle Results UI CSS updated.")

print("\nNext:")
print("1. Keep the Flask server running.")
print("2. Return to the ML Arena browser tab.")
print("3. Press Ctrl + Shift + R for a hard refresh.")
print("4. Click Battle results in the left sidebar.")
input("\nPress Enter to close...")
